    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("नूतनचन्द्रं पश्यतु।", "हे अल्लाहः, अयं चन्द्रः अस्माभिः उपरि आशीर्वादेन, विश्वासेन, सुरक्षया, इस्लाम्-मतेन च उदयोः। (हे चन्द्रः) मम प्रभुः, भवतः प्रभुः च अल्लाहः अस्ति।", "नवचन्द्रं दृष्ट्वा।", "प्रत्येकमासस्य नूतनस्य कृते सुन्नत-दुआ अस्ति।"),
        "dua_janaza_adult" to DuaText("जनाज़ा-प्रार्थना (वयस्क)", "हे अल्लाहः, अस्माकं जीवितान् मृतान्, उपस्थितान्, अनुपस्थितान्, अस्माकं युवान्, वृद्धान्, पुरुषान्, स्त्रीन् च क्षमिष्यति। हे अल्लाहः, अस्माकं मध्ये यः कश्चित् जीवति, तं इस्लाम्-मतस्य आधारेण जीवति, यः कश्चित् विश्वासे मरणम् आनयति, तं विश्वासेन म्रियताम्।", "अन्तिम-प्रार्थनायाः तृतीये तक्बीर् इत्यस्य अनन्तरं।", "मृतस्य वयस्कस्य कृते सुन्नह् दुआ।"),
        "dua_janaza_child" to DuaText("जनाज़ा-प्रार्थना (बाल)", "हे अल्लाहः, तं अस्माकं अग्रदूतः (आतिथेयः) करोतु, तस्य कृते पुरस्कारं धनम् च करोतु, तस्य मध्यस्थं करोतु यस्य मध्यस्थता स्वीकृतः।", "बालस्य अन्त्येष्टिक्रिये प्रार्थनायां (बालिकायाः कृते'इजल्हा'इति वदति)।", "हनाफ़ी-जनाः सुन्नह्-दुआ इत्यस्य अभ्यासं कुर्वन्ति स्म।"),
        "dua_mayyit_awf" to DuaText("मृतानां कृते विस्तृतः दुआ", "हे अल्लाहः, तं क्षमाय, तस्य प्रति करुणां करोतु, तस्य कल्याणं करोतु, क्षमायतु च। तस्य स्वागतम् सम्मानीयं करोतु, तस्य समाधिः विशालं करोतु, जलं, हिमं, शिलापातः च धौताम्, श्वेतवस्त्रं मलिनं भवति चेत् पापात् च शुद्धा करोतु।", "अन्त्येष्टिक्रिये प्रार्थनायां अथवा मृतस्य कृते।", "अव्फ् इब्न् मलिक् (र. अ.)-वर्यः इच्छति यत् सः मृतः व्यक्तिः आसीत् इति।"),
        "dua_visiting_graves" to DuaText("समाधिः सन्दर्शयतु।", "हे ईमानवालो, मुस्लिमवासियो, भवते शान्तिः भवतु। वयं अपि यदि अल्लाहः इच्छाम तर्हि भवन्तः सह मिलितुं शक्नुमः। अहं अल्लाहं प्रार्थयेते यत् अस्माभिः भवतः च कल्याणम्।", "यदा स्मशानप्रवेशः भवति।", "समाधि-दर्शनम् मृत्युं परित्यागं च स्मारयति।"),
        "dua_closing_eyes" to DuaText("मृतस्य नेत्रं बन्धयित्वा", "हे अल्लाहः, क्षमा करो, मार्गदर्शीनां मध्ये तस्य पदम् वर्धय, यः सः परित्यक्तवान् तस्य उत्तराधिकारी भव। हे जगतः प्रभुः, अस्मान् तस्य च क्षमा करोतु, तस्य समाधिः विशालं करोतु, प्रकाशेन पूरयतु।", "मृतस्य नेत्रं बन्धयति (तस्य नाम उल्लिखति)।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः अबू सलमा (र) इत्यस्य कृते एतत् दुआ कृतवान्।"),
        "dua_condolence" to DuaText("संवेदना (तज़िया)", "निश्चयमेव अल्लाहस्य एव अस्ति यत् सः गृहीतवान्, यत् सः दत्तवान् तत् तस्य एव अस्ति, तस्यैकं च सर्वं निर्दिष्टकालमिति भवति, अतः धैर्यम् आचरतु, पुरस्कारस्य आशां करोतु।", "मृत्योः अनन्तरं परिवाराय शोकं समर्पयति।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् स्वपुत्रीं प्रति अयं सन्देशम् अयापयत्।"),
        "dua_placing_in_grave" to DuaText("मृतं समाधिस्थानं स्थापयतु।", "अल्लाहस्य नाम्नं, अल्लाहस्य दूतः मार्गेन च।", "यदा मृतं समाधिस्थलं प्रति निक्षिप्तं भवति।", "सुन्नाह् दुआ इति समापनं।"),
        "dua_sneezing" to DuaText("शङ्घाः।", "सर्वस्य स्तुतिः अल्लाहस्य एव अस्ति।-अल्लाहः भवतः प्रति करुणां करिष्यति।-अल्लाहः भवतः मार्गः निर्देशं करिष्यति, भवतः कार्यान् सम्यक् करिष्यति।", "शङ्खे सति श्रोता'यारहमुकल्ला'इति वदति, ततः यः शङ्खे सः प्रत्युत्तरं ददति।", "अन्यस्य मुस्लिम् इत्यस्य उपरि मुस्लिम् इत्यस्य अधिकारः अस्ति।"),
        "dua_toilet_enter" to DuaText("शौचालयं प्रविशति।", "अल्लाहस्य नाम्नः। हे अल्लाहः, अहं अशुद्ध-जिन्न-पुरुषाणां स्त्रीणां च शरणं प्रार्थये।", "शौचालयं प्रवेष्टुं पूर्वं वामपादेन सह।", "बिस्मिल्ला इति जिन्नस्य व्यक्तेः च मध्ये परदायाः भवति।"),
        "dua_toilet_exit" to DuaText("शौचालयात् बहिः गच्छतु।", "(हे अल्लाह) अहं तव क्षमाः याचामि।", "यदा दक्षिणपादेन शौचालयात् बहिः गच्छति।", "प्रवाचकः सल्लल्लाहु अलैहि वसल्लम् इत्येषः शौचालयात् बहिः गत्वा एतत् उक्तवान्।"),
        "dua_thanking" to DuaText("कस्यापि धन्यवादम्।", "अल्लाहः भवते सत्कर्मं प्रतिफलं ददातु।", "यदा कश्चित् भवतः उपकारं करोति।", "यः कश्चित् एतत् वदति सः पूर्णतया कृतज्ञतां प्रकटयति।"),
        "dua_love_for_allah" to DuaText("यदा कश्चित् वदति,'अहं अल्लाहस्य कृते युष्मभ्यम् प्रेम करोमि'इति।", "सः (अल्लाहः) यः त्वं मह्यं प्रेम करोति, सः युष्मपि प्रेम कुरु।", "यदा कश्चित् वदति,'अल्लाहस्य कारणात् अहं युष्मासु प्रीयते'इति।", "अल्लाहस्य कृते प्रेमम् इति सुन्नः प्रत्युत्तरं ददति।"),
        "dua_seeing_muslim_smile" to DuaText("नमस्कारं (नमस्कारं)", "भवतः शान्तिः, अल्लाहस्य कृपा, तस्य आशीर्वादः च भवते।", "यदा मुस्लिम्-जनम् मिलितवान्।", "पूर्णसल्लम् इति वदन् त्रिशः सत्क्रियः अर्जयन्ति।"),
        "dua_dressing" to DuaText("वस्त्रधारणं", "सर्वस्य प्रशंसायाः अल्लाहस्य एव, यः मम कृते किमपि शक्ति-शक्ति-विना एतत् परिधानं कृत्वा तत् प्रददात्।", "यदा वस्त्रधारणं भवति।", "पूर्वकालस्य पापाणां क्षमाक्रमणः इति शुभसूचना।"),
        "dua_rooster_donkey" to DuaText("कुक्कुटस्य वा गधायाः वा श्रवणम्", "हे अल्लाहः, अहं तव अनुग्रहं (कोषकं) प्रार्थयेते।-- अहं शप्तात् (गधायाः) शय्यात् अल्लाहस्य शरणं प्रार्थये।", "कुक्कुटस्य शब्दम् आलपयित्वा अल्लाहस्य अनुग्रहं याचतु; गधायाः ब्राय् इत्यस्य शब्दम् आलपयित्वा शैतान् इत्यतः आश्रयं याचतु।", "कोष्टः दूतं, गधः शैतानं च पश्यन्ति।"),
        "dua_something_liked" to DuaText("प्रशंसनीयम् किमपि पश्यतु (दुष्टदृष्टेः विरुद्धं)", "अल्लाहः यत् इच्छति तत् करोतु। हे अल्लाहः, तत् अनुग्रहि।", "कस्यापि प्रशंसनीयं किमपि दृष्ट्वा, आशीर्वादार्थं प्रार्थयतु।", "आशीर्वादार्थं प्रार्थनया दुष्टः नेत्रः निवार्यते।"),
        "dua_sell_buy_debt_repaid" to DuaText("ऋणस्य पुनः परिशोधनं यदा भवति", "ईश्वरः भवतः कुटुम्बे धनसम्पदे च आशीर्वादं कुरु।", "ऋणदातुः ऋणस्य प्रतिदानकाले।", "ऋणं प्रतिदातुं धन्यवादं प्रतिदानम् च भवति।"),
        "dua_talbiyah" to DuaText("ताल्बिया", "हे अल्लाह, अहं इदानीं। अहं इदानीं, भवतः किमपि सहभागि नास्ति, अहं इतो अस्ति। निश्चयेन सर्वम् प्रशंसां, आशीर्वादं, आधिपत्यं च भवतः एव। भवतः किमपि सहभागि नास्ति।", "इह्राम्-मध्ये प्रवेशं कृत्वा उच्चैः।", "हज्-यात्रा तथा उम्रा-यात्राः इति प्रतीकम्।"),
        "dua_yamani_hajar" to DuaText("रुक्न् यमानी तथा हजार् अस्वाड् मध्ये", "हे अस्माकं प्रभुः, अस्मिन् जगते अस्मान् सत्करं परकाले च सत्करं ददातु, अग्न्योः दण्डात् अस्मान् रक्षयतु।", "तवाफ़्-मध्ये, येमेनी-मूलायाः कृष्णशिलायाः च मध्ये अस्ति।", "अस्मिन् स्थाने तवफ़्-नगरे पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इदं पठितवान्।"),
        "dua_safa_marwa" to DuaText("सफा तथा मार्वा विषये", "अल्लाहः विना, केवलम्, साझीदारः, पूजनीयः अधिकारः नास्ति। प्रभुत्वम् तस्य एव, स्तुतिः तस्य एव, सर्वविषयेषु च तस्य अधिकारः अस्ति। केवलं अल्लाहः अतिरिच्य पूजनीयः अधिकारः नास्ति। सः स्वप्रमाणं पूरितवान्, स्वदासस्य साहाय्यं कृतवान्, केवलं सङ्घस्य पराजयं कृतवान्।", "सफा-आरोहणं, किब्लाह्-नगरं प्रति अभिमुखम् (त्रिवारं)।", "सफा-मार्वा-विषये पैगम्बरस्य दिक्रः।"),
        "dua_arafah" to DuaText("अराफा-दिवसस्य सर्वोत्तमः दुआ", "अल्लाहः विना, यः एकलोः, साझीदारः, तस्यैवं पूजनीयः अधिकारः नास्ति। प्रभुत्वम् तस्य एव, स्तुतिः तस्यै, सर्वविषयेषु च सः अधिकारयुक्तः।", "अराफाह-दिवसः सर्वोत्तमः दुआ अस्ति।", "अराफा-दिवसस्य दुआ इति सर्वोत्तमः दुआ अस्ति, एते च उत्तमानि शब्दानि सन्ति।"),
        "dua_takbeer_tashreeq" to DuaText("तकबीर्-ए-तश्रीक्", "अल्लाहः सर्वश्रेष्ठः, अल्लाहः सर्वश्रेष्ठः। अल्लाहः अतिरिच्य अन्यत् ईश्वरः नास्ति। अल्लाहः सर्वश्रेष्ठः, अल्लाहः सर्वश्रेष्ठः, सर्व प्रशंसा अल्लाहस्य एव।", "9 धुल्-हिज्जा इत्यस्य फजरतः 13 धुल्-हिज्जा इत्यस्य अस्र् पर्यन्तं प्रत्येकं अनिवार्य-प्रार्थनायाः अनन्तरं।", "अली तथा इब्न-मसूद् (र. अ.) इत्येतयोः प्रतिवेदनम्-हनाफ़ी-मतानुगुणं वाजिब् इति।"),
        "dua_zamzam" to DuaText("ज़मज़म् पीयते।", "हे अल्लाहः, अहं युष्मभ्यम् हितकरं ज्ञानं, विपुलं पोषणं, प्रत्येकस्य रोगस्य उपचारं च प्रार्थये।", "ज़म्ज़म्-पानीयं कुर्वन्, भवतः इच्छायाः कृते दुआ करोतु।", "ज़मज़म् इति यत् किमपि पीयते तस्य कृते अस्ति (इब्न् माजाह् 3062)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("सृष्टेः विषये चिन्तयतु।", "हे अस्माकं प्रभुः, त्वं एतावत् व्यर्थम् न सृष्टवान्। त्वं महिमावान् अस्मि, अतः अग्न्युत्पादनात् अस्मान् रक्षय।", "ये स्वर्गस्य पृथिव्या च सृष्टिं चिन्तयन्ति तेषां दुआ।", "विवेकशीलानां दुवा (उलुल्-अलबाब)।"),
        "dua_q_sami_na_munadiyan" to DuaText("वयं विश्वासाय आह्वयतां श्रुतवन्तः।", "हे अस्माकं प्रभुः, वयं एकम् आह्वयन्तं विश्वसनीयं श्रुतवन्तः, यः कथितवान्,'भवतः प्रभुम् विश्वसन्तु'इति, वयं विश्वसितवन्तः। हे अस्माकं प्रभुः, अस्माकं पापानि क्षमाय, अस्माकं दुष्कृत्यानि निष्कासय, धार्म्मिकैः सह म्रियताम्।", "विश्वासस्य, धार्म्मिकानां मध्ये मृत्योः च कृते दुआ।", "क्षमाश्च उत्तमसमाप्तेः च दुआ।"),
        "dua_q_atina_ma_waadtana" to DuaText("त्वं यत् प्रतिज्ञां कृतवान् तत् आमाम् अददातु।", "हे अस्माकं प्रभुः, त्वं स्वस्य दूतानां द्वारा यत् प्रतिज्ञां कृतवान् तत् अस्मान् प्रददातु, पुनरुत्थानदिने अस्मान् न अपमानितं करोतु। निःसन्देहं त्वं प्रतिज्ञां न भङ्गं करोति।", "पुनरुत्थानदिने अपमानात् शरणम्।", "परकाले सम्मानं अन्विष्यत।"),
        "dua_q_israfana" to DuaText("अस्माकं अतिरक्तान् क्षमिष्यतु।", "हे अस्माकं प्रभुः, अस्माकं पापानि, अस्माकं कार्येषु अतिर्यकानि च क्षमिष्यति, अस्माकं पादानि दृढानि कुरु, अविश्वासिनां विरुद्धं साहाय्यं कुरु।", "पूर्ववर्तिनां पैगम्बरानां सहचरानां दुआ।", "दृढतायाः क्षमाकरणस्य च दुआ।"),
        "dua_q_jamiun_nas" to DuaText("भवान् मानवजातिं सङ्गृहीष्यति।", "हे अस्माकं प्रभुः, भवान् निश्चयेन जनान् तस्मिन् दिने समागमिष्यति यस्मिन् निःसन्देहे। निःसन्देहः अल्लाहः स्वप्रत्याशां न भङ्गयति।", "पुनरुत्थानदिने निश्चयः।", "तेषां द्वयः दृढतया ज्ञाने स्थिताः सन्ति।"),
        "dua_q_maash_shahidin" to DuaText("साक्षिनां मध्ये अस्मान् लेखतु।", "हे अस्माकं प्रभुः, वयं विश्वसितवन्तः, अतः साक्षिनां मध्ये लेखतु।", "ये सत्यम् अङ्गीकृतवन्तः विश्वसन्ति तेषां दुआ।", "विश्वासस्य स्वीकारार्थं दुआ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("न दुष्कृत्यकर्तृभिः सह।", "हे अस्माकं प्रभुः, दुष्कृत्यं कुर्वतां जनैः सह मा स्थापय।", "अल्-अराफ़स्य जनानां दुआ।", "अन्यायिनः भवितुं शरणं प्राप्नुयात्।"),
        "dua_q_tawaffana_muslimin" to DuaText("मुस्लिमरूपेण धैर्यम् तथा मृत्युः", "हे भगवते, अस्माकं उपरि धैर्यम् धारय, अस्मान् मुस्लिमरूपेण म्रियताम्।", "यदा ते विश्वसितवन्तः तदा फ़रोहनस्य यादुकरानां दुआ।", "परीक्षणस्य धैर्यम्, विश्वासस्य अन्तः च।"),
        "dua_q_la_tajalna_fitnah" to DuaText("न उत्पीडकेभ्यः परीक्षणम्।", "अल्लाहस्य उपरि वयं आश्रित्यामः। हे अस्माकं प्रभुः, अस्मान् दुष्कृत्यकारिणां कृते परीक्षां मा करोतु, अस्मान् स्वस्य करुणया अविश्वासिनः जनान् परिहरतु।", "मूसा (ए. एस्.) इत्यस्य जनानां दुआ।", "द्रोहात् उत्पीडनात् च रक्षाय दुआ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("नूह् (अ. स.) इत्यस्य दुआ-क्षमा-हेतुः।", "हे मम प्रभुः, यस्मात् विषये अहं अज्ञानोस्मि तस्य प्रार्थनाय अहं तव शरणं याचामि। यदि त्वं माम् क्षमातुं मम प्रति करुणां न करोति तर्हि अहं क्षत्यासु ममान्तिके भविष्यति।", "पैगम्बरः नूह् (अ. स.) इत्यस्य पश्चात्तापस्य दुआ।", "उचित-आचार-व्यवहारेन पृच्छने एकः पाठः।"),
        "dua_q_mudkhala_sidq" to DuaText("सत्यस्य प्रवेशः निर्गमनः च", "हे मम प्रभुः, सत्येन सह प्रवेष्टुं सत्येन सह निर्गमितुं च मां प्रेरयतु, तथा च स्वात् समर्थनं कर्तुम् अधिकारं ददातु।", "नूतनं कार्यं प्रवेष्टुं पूर्वं, गृहं वा स्थानं वा।", "हिजरतस्य समये दुआ-धर्मः पैगम्बरं उपदेशयत्।"),
        "dua_q_la_tadharni_fardan" to DuaText("ज़कारिया-इत्यस्य दुआ (ए. एस्.)-मा मा वदतु।", "हे मम प्रभुः, मां मा परित्याज्य, त्वं एव श्रेष्ठः उत्तराधिकारी।", "तेषां कृते ये बालान् अन्विष्यन्ति।", "अस्य द्वया अल्लाहः याह्या (ए. एस्.) इति प्रदानं कृतवान्।"),
        "dua_q_munzalan_mubarakan" to DuaText("धन्यं अवतरणस्थानम्", "हे मम प्रभुः, धन्यस्थाने मां गन्तुं दे, तथा च भूमिं प्रति आनेतानां मध्ये त्वं उत्तमः।", "यदा नूतनं गृहं गच्छति अथवा कस्मिंश्चित् स्थितेः-नूह् (ए. एस्.) इत्यस्य दुआ।", "नूतनस्थाने आशीर्वादार्थं दुआ।"),
        "dua_q_amanna_faghfir" to DuaText("वयं विश्वसामः, अतः अस्मान् क्षमागृहे।", "हे अस्माकं प्रभुः, वयं विश्वसितवन्तः, अतः अस्मान् क्षमतु, अस्माभिः सह करुणामयं कुरु, त्वं च करुणामयिषु श्रेष्ठः।", "अल्लाहस्य पुण्यवानानां दासानां द्वयः।", "क्षमाश्च दयेः च समग्रः दुआ।"),
        "dua_q_isrif_jahannam" to DuaText("नरकस्य दण्डं निवारयतु।", "हे अस्माकं प्रभुः, अस्माभिः नरकस्य दण्डं निवारय। निःसन्देहं तस्य दण्डः नित्यः भवति। निःसन्देहं तत् दुष्टं वासस्थानम् अस्ति।", "परम करुणामयी ('इबादत-रहमानः') इत्यस्य सेवकाणां दुआ।", "नरकात् शरणार्थं कुरान्-द्वयः।"),
        "dua_q_hab_li_hukman" to DuaText("इब्राहिमस्य दुआ (अ. स.)-ज्ञानम् तथा जन्नत", "हे मम प्रभुः, मह्यं ज्ञानम् दानम्, धार्म्मिकैः सह सह सह, पश्चात् पीढिषु मह्यं सम्मान्यं उल्लेखं दत्तं, आनन्द-उद्यानस्य उत्तराधिकारिनां मध्ये मह्यं स्थापयतु।", "ज्ञानस्य याचना, धार्म्मिकस्य स्वर्गस्य च सङ्गः।", "इब्राहिम् (अ. स.) इत्यस्य समग्रः दुआ।"),
    )
}
